    adj = {n: [] for n in nodes}
    in_degree = {n: 0 for n in nodes}

    # Add all edge endpoints to nodes if not already present
    for u, v in edges:
        if u not in adj:
            adj[u] = []
            in_degree[u] = 0
        if v not in adj:
            adj[v] = []
            in_degree[v] = 0

    # Use a set to ignore duplicate edges
