def lru(capacity, operations):
    if capacity == 0:
        return [-1] * sum(1 for op in operations if op[0] == "get")

    cache = {}
    order = []
    results = []

    for op in operations:
        if op[0] == "put":
            key, value = op[1], op[2]
            if key in cache:
                cache[key] = value
                order.remove(key)
                order.append(key)
            else:
                if len(cache) >= capacity:
                    lru_key = order.pop(0)
                    del cache[lru_key]
                cache[key] = value
                order.append(key)
        else:
            key = op[1]
            if key in cache:
                results.append(cache[key])
                order.remove(key)
                order.append(key)
            else:
                results.append(-1)

    return results
